"""
The HOA management glossary lifted from sublimepersonnel.com/hoa-glossary.

Pete agreed on the Aug 28 call that this should not survive as a standalone page
("I'm not going to migrate this page… I think it might be bloat"). Nobody reads a
wall of definitions. It is still a genuine AEO/GEO asset, so it lives here and is
emitted into llms.txt for the models, and is the source material for the HOA blog
spokes that carry it for humans.

Terms are verbatim from the client's own page — do not paraphrase them without
asking, they are the client's published definitions.
"""

GLOSSARY = [
 ("Architectural Review Committee (ARC)", "A committee responsible for reviewing and approving homeowner requests involving exterior modifications, landscaping changes, paint colors, fences, additions, and other visible property alterations."),
 ("Assessment", "A fee paid by homeowners to support community operations, maintenance, reserves, and services provided by the HOA."),
 ("Annual Meeting", "A required yearly meeting where homeowners and board members discuss association business, budgets, elections, and community updates."),
 ("Board of Directors", "The elected group of homeowners responsible for governing the HOA and making operational and financial decisions."),
 ("Bylaws", "The governing rules that define how an HOA operates, including elections, meetings, board responsibilities, and procedures."),
 ("Capital Improvement", "A major project or upgrade intended to increase property value or extend the life of community assets, such as pools, roads, or clubhouse renovations."),
 ("Capital Reserve Fund", "Money set aside for future major repairs and replacements."),
 ("CC&Rs (Covenants, Conditions, and Restrictions)", "Legal governing documents that establish community rules, restrictions, and homeowner responsibilities."),
 ("Community Association Manager (CAM)", "A professional who manages HOA operations, vendors, finances, communication, and daily administration."),
 ("Compliance", "Ensuring homeowners and the association follow governing documents and established community rules."),
 ("Delinquency", "Unpaid HOA assessments or fees that are overdue."),
 ("Deed Restrictions", "Rules legally attached to a property that limit certain uses or activities."),
 ("Election Quorum", "The minimum number of members required to conduct official HOA business or voting."),
 ("Executive Session", "A closed board meeting used for confidential discussions involving legal matters, personnel issues, collections, or sensitive topics."),
 ("Fiduciary Duty", "The legal obligation requiring board members to act in the best interest of the community."),
 ("Fine", "A monetary penalty assessed for violations of HOA rules or governing documents."),
 ("Governing Documents", "The collection of legal documents that establish and regulate the HOA: Articles of Incorporation, Bylaws, CC&Rs, and Rules and Regulations."),
 ("Homeowners Association (HOA)", "An organization that manages and maintains a residential community and enforces governing documents."),
 ("Lien", "A legal claim placed on property due to unpaid assessments or debts."),
 ("Management Company", "A third-party organization hired by an HOA to manage community operations."),
 ("Minutes", "Official written records documenting decisions and discussions from HOA meetings."),
 ("Operating Budget", "The annual financial plan outlining expected expenses and revenue."),
 ("Proxy Vote", "Authorization allowing one homeowner to vote on behalf of another homeowner."),
 ("Quorum", "The minimum attendance requirement needed to conduct official meetings or voting."),
 ("Reserve Study", "A financial analysis that estimates future repair and replacement costs and determines reserve funding requirements."),
 ("Rules and Regulations", "Specific community guidelines that supplement governing documents and address day-to-day behavior."),
 ("Special Assessment", "An additional fee charged to homeowners when regular assessments are insufficient to cover unexpected expenses."),
 ("Vendor Management", "The process of selecting, coordinating, and overseeing contractors and service providers."),
 ("Violation Notice", "A formal notice informing a homeowner of a rule or governing document violation."),
 ("Work Order", "A request issued for maintenance or repair work within the community."),
 ("Community Associations Institute (CAI)", "A professional organization providing education, resources, and certifications for HOA professionals."),
 ("Property Management Software", "Technology platforms used for accounting, resident communication, work orders, violations, and operational management."),
 ("Reserve Funding Percentage", "The amount of reserve funds available compared to projected future repair obligations."),
 ("Self-Managed HOA", "An association managed directly by its board without hiring a third-party management company."),
 ("Transition Meeting", "A meeting where a developer transfers operational control of the HOA to homeowners."),
 ("Master-Planned Community", "A large community developed with integrated amenities, common areas, and long-term infrastructure planning."),
]

# Recruiting and marketing terms — the ones that carry search intent.
RECRUITING_TERMS = [
 ("HOA Management", "The process of overseeing and managing the daily operations, maintenance, financial activities, and administrative responsibilities of a homeowners association. HOA management helps maintain community standards, property values, and resident satisfaction."),
 ("Community Association Management", "The professional administration and coordination of residential communities, including homeowners associations, condominium associations, and master-planned communities. Includes financial oversight, vendor coordination, resident communication, and compliance management."),
 ("Community Manager", "A professional responsible for overseeing the day-to-day operations of a community association: homeowner communication, vendors, budgets, maintenance requests, board support, and enforcement of community guidelines."),
 ("HOA Staffing", "The process of identifying, hiring, and placing qualified professionals into roles within homeowners associations and community management organizations, including community managers, administrative staff, accounting personnel, and leadership roles."),
 ("HOA Recruiting", "A specialized hiring process focused on attracting, screening, and placing qualified candidates for homeowners associations and property management organizations, targeting candidates with industry experience, governing document knowledge, and strong communication skills."),
 ("CAM Certification", "Community Association Manager certification is a professional credential demonstrating knowledge and qualifications in community association management practices, operations, and regulations. Requirements vary by state."),
]
